<span class="line"><span style="color:#ABB2BF;">        total </span><span style="color:#56B6C2;">+=</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;">(t </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> math.</span><span style="color:#61AFEF;">log</span><span style="color:#ABB2BF;">(p_clipped) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;"> t) </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> math.</span><span style="color:#61AFEF;">log</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;"> p_clipped))</span></span>
